try:
 def f(*args: *()): pass
except Exception as e: print(type(e).__name__,str(e))

try:
 def f(*args: *(1,2)): pass
except Exception as e: print(type(e).__name__,str(e))

try:
 def f(*args: *42): pass
except Exception as e: print(type(e).__name__,str(e))

class Ann:
 def __iter__(self):
  print('iter')
  yield 'ok'
def f(*args: *Ann()): pass
print(f.__annotations__)

events=[]
def build():
 events.append('value')
 return [42]
def default():
 events.append('default')
 return 0
def decorate(f):
 events.append('decorate')
 return f
@decorate
def helper(x=default(), *args: *build()): pass
print(events, helper.__annotations__)

def packed():
 print('first')
 yield 1
 print('second')
 yield 2
 print('third')
 yield 3
try:
 def helper(*args: *packed()): pass
except Exception as e: print(type(e).__name__,str(e))

class Bad:
 def __iter__(self): raise MemoryError('guest')
try:
 def helper(*args: *Bad()): pass
except MemoryError as e: print('caught',str(e))

class Pack:
 def __iter__(self): return self
 def __next__(self):
  if hasattr(self,'done'): raise StopIteration
  self.done=True
  return 7
 def __length_hint__(self): raise AssertionError('hint')
def helper(*args: *Pack()): pass
print(helper.__annotations__)

from typing import TypeVar
T=TypeVar('T')
try:
 def helper(*args: *T): pass
except Exception as e: print(type(e).__name__,str(e))
